#!/usr/bin/env python3
"""
Round 156k (culprits), 4 October 2026. Needs round 155k.

Redraws the seventh basemap like the Earth First! artwork.

Run from the repository root (the apply-patch workflow does).
"""
import base64, pathlib, subprocess, sys, tempfile

NOTES = ['## Round 156k (4 October)\n\nNeeds round 155k. No tiles patch. No app.js?v= bump. The seventh basemap redrawn again.\n\n- Owner on 155k, with two scans of Earth First! artwork (a moonlit mountain,\n  a wolf among conifers): too much of a black-and-white theme, not the Earth\n  First! look; fewer squiggles and patterns, natural hand-crafted intricate\n  shadows. Nothing from any picture is copied.\n- inkDrawSquare redone in the manner of those drawings: shadow sides solid\n  black with ragged, blotchy edges and a few fine white scratches; half-tones\n  in fine, short, straight pen strokes down the fall line (directions in\n  twelfths of a turn from heavily smoothed slopes, chosen patch by patch;\n  strokes fixed in place and drawn whole, the tone deciding how many and how\n  thick); light ground paper with sparse stipple; the sea white paper\n  stippled with round, uneven dots, closer over the deeps, with bare paper\n  and one ragged inked line along the shore. No wavy cuts, no wander.\n  About 60-90 ms a square in Chromium.\n- Close in: no drawn motifs. Forests dense stipple, wetlands and towns light\n  stipple, sea (from zoom 7) and lakes medium stipple (256 px sheets of\n  chance-placed dots), buildings solid black. Layer colours "suited to the\n  basemap": deep (pale ground again). Menu name unchanged: Black and white.\n- Checked in Chromium with sample heights (zooms 0-2); not seen against the\n  live height tiles.\n']


def git(*a, check=True):
    return subprocess.run(["git", *a], capture_output=True, text=True, check=check)


def main():
    root = pathlib.Path(".")
    if not (root / "map" / "app.js").exists():
        sys.exit("round156k: run from the culprits repository root")
    h = root / "HANDOFF.md"
    if "## Round 155k" not in h.read_text(encoding="utf-8"):
        sys.exit("round156k: round 155k must be applied first")
    with tempfile.NamedTemporaryFile("wb", suffix=".diff", delete=False) as f:
        f.write(base64.b64decode(DIFF))
        path = f.name
    if git("apply", "--check", "-R", "--binary", path, check=False).returncode == 0:
        print("round156k: already applied")
    else:
        r = git("apply", "--3way", "--binary", path, check=False)
        if r.returncode != 0:
            git("checkout", "--", "map/app.js", "map/test.mjs", check=False)
            sys.exit("round156k: the diff did not apply:\n" + r.stdout + r.stderr)
        print("round156k: applied")
    text = h.read_text(encoding="utf-8")
    add = "".join(n if n.endswith("\n\n") else n.rstrip("\n") + "\n\n" for n in NOTES if n.split("\n", 1)[0] not in text)
    if add:
        at = text.index("\n## Round ") + 1
        h.write_text(text[:at] + add + text[at:], encoding="utf-8")


DIFF = ''

if __name__ == "__main__":
    main()
